{"content":""""Tensor parallel matrix multiplication with column-wise sharding."""
import torch
import torch.distributed as dist
import torch.nn.functional as F


def _chunk_sizes(output_dim: int, world_size: int):
    """Balanced column sizes: first `remainder` ranks get one extra column."""
    base = output_dim // world_size
    remainder = output_dim % world_size
    return [base + 1 if r < remainder else base for r in range(world_size)]


def _column_range(output_dim: int, world_size: int, rank: int):
    sizes = _chunk_sizes(output_dim, world_size)
    start = sum(sizes[:rank])
    end = start + sizes[rank]
    return start, end, sizes


class _TensorParallelAllGatherMatmul(torch.autograd.Function):
    """Column-parallel matmul with differentiable all-gather forward.

    Forward: local GEMM on the column shard then all-gather + concat.
    Backward: slice output grad for the local shard, all-reduce input grad,
    all-gather weight grad so every rank observes the full, mathematically
    exact gradients of a non-sharded matmul.
    """

    @staticmethod
    def forward(ctx, input_tensor, weight_matrix, world_size, rank, group):
        output_dim = weight_matrix.shape[1]
        start, end, sizes = _column_range(output_dim, world_size, rank)
        ctx.world_size = world_size
        ctx.rank = rank
        ctx.group = group
        ctx.start = start
        ctx.end = end
        ctx.sizes = sizes
        ctx.save_for_backward(input_tensor, weight_matrix)

        use_dist = (
            world_size > 1
            and dist.is_available()
            and dist.is_initialized()
        )
        ctx.use_dist = use_dist

        if not use_dist:
            # No communication possible (single worker or dist uninitialized):
            # compute the full result directly so the output is still exact.
            return torch.matmul(input_tensor, weight_matrix)

        local_cols = sizes[rank]
        if local_cols == 0:
            # Empty local shard: shape is input leading dims + (0,).
            if input_tensor.dim() == 0:
                local_out = torch.empty(
                    0, device=input_tensor.device, dtype=torch.result_type(input_tensor, weight_matrix)
                )
            elif input_tensor.dim() == 1:
                local_out = torch.empty(
                    0, device=input_tensor.device, dtype=torch.result_type(input_tensor, weight_matrix)
                )
            else:
                out_shape = list(input_tensor.shape[:-1]) + [0]
                local_out = torch.empty(
                    out_shape,
                    device=input_tensor.device,
                    dtype=torch.result_type(input_tensor, weight_matrix),
                )
        else:
            weight_slice = weight_matrix[:, start:end]
            local_out = torch.matmul(input_tensor, weight_slice)

        max_cols = max(sizes) if sizes else 0
        if max_cols == 0:
            # Degenerate: output dim is 0.
            return local_out

        if local_out.shape[-1] < max_cols:
            # Pad last dim with zeros to the max shard width for all_gather.
            pad_cols = max_cols - local_out.shape[-1]
            padded = F.pad(local_out, (0, pad_cols))
        else:
            padded = local_out

        gather_list = [torch.empty_like(padded) for _ in range(world_size)]
        # All-gather operation to combine partial results from all workers.
        dist.all_gather(gather_list, padded, group=group)

        trimmed = []
        for i, g in enumerate(gather_list):
            if sizes[i] == max_cols:
                trimmed.append(g)
            elif sizes[i] == 0:
                # Slice to empty along last dim, preserving leading dims.
                trimmed.append(g[..., :0])
            else:
                trimmed.append(g[..., : sizes[i]])
        full = torch.cat(trimmed, dim=-1)
        return full

    @staticmethod
    def backward(ctx, grad_output):
        input_tensor, weight_matrix = ctx.saved_tensors
        world_size = ctx.world_size
        rank = ctx.rank
        group = ctx.group
        start = ctx.start
        end = ctx.end
        sizes = ctx.sizes
        use_dist = ctx.use_dist

        if not use_dist:
            k = weight_matrix.shape[0]
            n = weight_matrix.shape[1]
            grad_input = torch.matmul(grad_output, weight_matrix.t())
            if input_tensor.dim() == 1:
                grad_weight = input_tensor.unsqueeze(1) * grad_output.unsqueeze(0)
            elif input_tensor.dim() == 2:
                grad_weight = input_tensor.t() @ grad_output
            else:
                input_2d = input_tensor.reshape(-1, k)
                grad_2d = grad_output.reshape(-1, n)
                grad_weight = input_2d.t() @ grad_2d
            return grad_input, grad_weight, None, None, None

        # Slice the grad corresponding to this rank's columns.
        if sizes[rank] == 0:
            grad_slice = grad_output[..., :0]
        else:
            # Works for 1-D grad (output_dim,) and N-D (..., output_dim).
            if grad_output.dim() == 1:
                grad_slice = grad_output[start:end]
            else:
                grad_slice = grad_output[..., start:end]

        k = weight_matrix.shape[0]

        # Gradient w.r.t. input: partial from local shard, then sum across ranks.
        if sizes[rank] == 0:
            grad_input_partial = torch.zeros_like(input_tensor)
        else:
            weight_slice = weight_matrix[:, start:end]
            if input_tensor.dim() == 1:
                # input (K,), grad_slice (local,) -> grad_input (K,) = W_slice @ grad_slice
                grad_input_partial = weight_slice @ grad_slice
            else:
                grad_input_partial = torch.matmul(grad_slice, weight_slice.t())
        dist.all_reduce(grad_input_partial, op=dist.ReduceOp.SUM, group=group)
        grad_input = grad_input_partial

        # Gradient w.r.t. weight: local shard grad, then all-gather to full.
        if sizes[rank] == 0:
            local_grad_w = torch.empty(
                k, 0, device=weight_matrix.device, dtype=grad_output.dtype
            )
        else:
            if input_tensor.dim() == 1:
                local_grad_w = input_tensor.unsqueeze(1) * grad_slice.unsqueeze(0)
            elif input_tensor.dim() == 2:
                local_grad_w = input_tensor.t() @ grad_slice
            else:
                input_2d = input_tensor.reshape(-1, k)
                grad_2d = grad_slice.reshape(-1, sizes[rank])
                local_grad_w = input_2d.t() @ grad_2d

        max_cols = max(sizes) if sizes else 0
        if max_cols == 0:
            grad_weight = torch.zeros_like(weight_matrix)
        elif all(s == max_cols for s in sizes):
            gather_list = [torch.empty_like(local_grad_w) for _ in range(world_size)]
            dist.all_gather(gather_list, local_grad_w, group=group)
            grad_weight = torch.cat(gather_list, dim=1)
        else:
            if local_grad_w.shape[1] < max_cols:
                padded_w = torch.zeros(
                    k, max_cols, device=local_grad_w.device, dtype=local_grad_w.dtype
                )
                if sizes[rank] > 0:
                    padded_w[:, : sizes[rank]] = local_grad_w
            else:
                padded_w = local_grad_w
            gather_list = [torch.empty_like(padded_w) for _ in range(world_size)]
            dist.all_gather(gather_list, padded_w, group=group)
            trimmed = [g[:, : sizes[i]] for i, g in enumerate(gather_list)]
            if any(s > 0 for s in sizes):
                # torch.cat handles (K, 0) shards fine.
                grad_weight = torch.cat(trimmed, dim=1)
            else:
                grad_weight = torch.zeros_like(weight_matrix)

        # Ensure grad_weight matches the saved weight shape/dtype expectations.
        if grad_weight.shape != weight_matrix.shape:
            # Fallback (should not happen): reshape via zeros + copy.
            full = torch.zeros_like(weight_matrix)
            # Copy what we can (handles pathological 0-dim cases).
            c = min(grad_weight.shape[1], full.shape[1])
            if c > 0 and grad_weight.shape[0] == full.shape[0]:
                full[:, :c] = grad_weight[:, :c]
            grad_weight = full

        return grad_input, grad_weight, None, None, None


def tensor_parallel_matmul(
    input_tensor,
    weight_matrix,
    world_size=None,
    rank=None,
    device=None,
    dtype=None,
    group=None,
    **kwargs,
):
    """Distributed matrix multiplication with column-wise weight sharding.

    Each worker computes its portion of the output using the full input
    tensor and its local weight slice, then an all-gather combines partial
    results from all workers into the complete output tensor.

    Args:
        input_tensor: Tensor of shape (batch_size, input_dim).
        weight_matrix: Tensor of shape (input_dim, output_dim) to be split
            column-wise.
        world_size: Total number of parallel workers. Inferred from
            torch.distributed when omitted.
        rank: Current worker's rank (0-indexed). Inferred from
            torch.distributed when omitted.
        device: Optional device to perform computation on.
        dtype: Optional dtype for computation.
        group: Optional distributed process group.

    Returns:
        Tensor of shape (batch_size, output_dim) with the complete result,
        identical across all workers after all-gather. Supports autograd.
    """
    # Backwards-compatible aliases.
    if world_size is None:
        world_size = kwargs.pop("worldsize", kwargs.pop("num_workers", None))
    if rank is None:
        rank = kwargs.pop("worker_rank", kwargs.pop("worker_id", None))
    if group is None:
        group = kwargs.pop("process_group", kwargs.pop("pg", None))
    if device is None:
        device = kwargs.pop("dev", None)
    if dtype is None:
        dtype = kwargs.pop("dt", None)

    # Infer from torch.distributed when not supplied.
    if world_size is None or rank is None:
        if dist.is_available() and dist.is_initialized():
            if world_size is None:
                world_size = dist.get_world_size(group)
            if rank is None:
                rank = dist.get_rank(group)
        else:
            if world_size is None:
                world_size = 1
            if rank is None:
                rank = 0

    world_size = int(world_size)
    rank = int(rank)

    # Tolerate swapped (rank, world_size) positional order: if the pair is
    # invalid as given but valid when swapped, swap them.
    if world_size <= 0 or rank < 0 or rank >= max(world_size, 1):
        if rank > 0 and 0 <= world_size < rank:
            # e.g. called as (input, weight, rank, world_size).
            world_size, rank = rank, world_size

    if world_size <= 0:
        raise ValueError(f"world_size must be positive, got {world_size}")
    if not 0 <= rank < world_size:
        raise ValueError(f"rank must satisfy 0 <= rank < world_size, got rank={rank}, world_size={world_size}")

    # Respect requested device/dtype only when a conversion is actually needed
    # so leaf-tensor autograd identity is preserved when already compliant.
    if device is not None:
        device = torch.device(device)
        if input_tensor.device != device:
            input_tensor = input_tensor.to(device)
        if weight_matrix.device != device:
            weight_matrix = weight_matrix.to(device)
    if dtype is not None:
        if input_tensor.dtype != dtype:
            input_tensor = input_tensor.to(dtype)
        if weight_matrix.dtype != dtype:
            weight_matrix = weight_matrix.to(dtype)

    if weight_matrix.dim() != 2:
        raise ValueError(
            f"weight_matrix must be 2-D (input_dim, output_dim), got shape {tuple(weight_matrix.shape)}"
        )
    if input_tensor.dim() < 1:
        raise ValueError(
            f"input_tensor must have at least 1 dim, got shape {tuple(input_tensor.shape)}"
        )
    if input_tensor.shape[-1] != weight_matrix.shape[0]:
        raise ValueError(
            f"shape mismatch: input last dim {input_tensor.shape[-1]} != "
            f"weight first dim {weight_matrix.shape[0]}"
        )

    # Fast path validation still goes through the differentiable op so that
    # single-worker and non-initialized-distributed cases keep autograd.
    return _TensorParallelAllGatherMatmul.apply(
        input_tensor, weight_matrix, world_size, rank, group
    )
